// The skeleton's content (data/skeleton.json, generated by @aue/data): its map is in route coordinates, and the
// simulation runs it to the end the same way twice.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createWorld, step, stateHash } from '@aue/sim';
import { skeletonContent as c, skeletonSource } from '../src/index.js';

test('[地图-1] tiles are in route coordinates: start tiles at the top, every route starts on one', () => {
  const { tiles, height, routes } = c.level;
  const startRows = tiles.flatMap((row, r) => row.map((t) => (t.key.startsWith('tile_start') ? r : -1))).filter((r) => r >= 0);
  assert.ok(startRows.length > 0 && startRows.every((r) => r >= height - 2), `start tiles on rows ${startRows}`);
  for (const route of routes) assert.match(tiles[route.start.row][route.start.col].key, /^tile_start/, JSON.stringify(route.start));
  assert.match(skeletonSource.commit, /^[0-9a-f]{40}$|^unknown$/);
});

test('the skeleton plays out the same way twice', () => {
  /** @returns {number[]} */
  const play = () => {
    const w = createWorld(c, { seed: 42, players: 2 }), out = [];
    for (let f = 0; f < 4000; f++) {
      /** @type {[number, import('@aue/sim').Command][]} */
      const cmds = f === 0 ? [[0, { type: 'deploy', op: 'char_503_rang', row: 3, col: 2, dir: 0 }], [1, { type: 'deploy', op: 'char_502_nblade', row: 4, col: 5, dir: 2 }]] : [];
      step(w, c, cmds);
      if (f === 0) assert.equal(w.units.filter((u) => u.kind === 0).length, 2, 'both deploys succeed');
      if (f % 100 === 0) out.push(stateHash(w));
    }
    return out;
  };
  assert.deepEqual(play(), play());
});
